using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Adds or changes a custom local language pack to the current localization target
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetCustomLanguagePackAsync(LanguagePackInfo info = default, LanguagePackString[] strings = default)
    {

           using var activity =  StartCallActivity("SetCustomLanguagePackAsync", typeof(SetCustomLanguagePack).FullName ?? "SetCustomLanguagePackAsync");

           try
           {
             return client.SetCustomLanguagePackAsync(info, strings);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
